using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnPurgedActivateActionEffectCustomTag", menuName = "Data/Battle/Battle Actions/Tags/OnPurgedActivateActionEffectCustomTag", order = 0)]
public class OnPurgedActivateActionEffectCustomTag : Tag
{
	[SerializeField]
	private OnPurgedActivateActionEffect onPurgedActivateActionEffect;

	public override string GetTagDescription()
	{
		BattleAction battleAction = onPurgedActivateActionEffect.BattleAction;
		string localizedWhenEnemyDefeatedTagBase = ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedWhenEnemyDefeatedTagBase();
		string text = "";
		if (onPurgedActivateActionEffect.BlightedSoul)
		{
			text = "\n" + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedAfterFirstCantSeeMeterTagBase(onPurgedActivateActionEffect.GetLocalizedDescriptionExternal(), onPurgedActivateActionEffect);
		}
		return Smart.Format(arg1: battleAction.GetActionDescription(-1).LowercaseFirst(), format: localizedWhenEnemyDefeatedTagBase, arg0: onPurgedActivateActionEffect.GetEffectName()) + text;
	}
}
